-- =====================================================================
-- Frases da CHEGADA ao castelo.
-- {user} fala; {user1} é escolhido pelo teor; {user2} é outra pessoa presente.
-- =====================================================================

INSERT INTO phrases (phase, tone, behavior_id, text)
SELECT 'ARRIVAL'::phrase_phase, v.tone::phrase_tone, b.id, v.text
FROM (VALUES
  -- amizade
  ('FRIENDLY', 'Querido', '{user} já sabia o nome, a idade e o signo de {user1} antes de chegarem ao salão.'),
  ('FRIENDLY', 'Carente', '{user} abraçou {user1} três vezes em dez minutos. {user1} parou de contar.'),
  ('FRIENDLY', 'Amado', '{user} dividiu o guarda-chuva com {user1} na chuva escocesa, e isso bastou para virar amizade.'),
  ('FRIENDLY', 'Protetor', '{user} ajudou {user1} com a mala pela escadaria inteira: "Aqui ninguém fica para trás."'),
  ('FRIENDLY', 'Diplomata', '{user} apresentou {user1} a todo mundo como se fosse anfitrião(ã) do castelo.'),
  ('FRIENDLY', 'Brincalhão', '{user} fez {user1} rir tanto que o champanhe saiu pelo nariz.'),
  ('FRIENDLY', 'Ingênuo', '"Você tem cara de quem nunca mentiu na vida", disse {user} para {user1}. Nunca se sabe.'),
  ('FRIENDLY', NULL, '{user} e {user1} descobriram que torcem para o mesmo time. Pronto, aliança espiritual selada.'),
  ('FRIENDLY', NULL, '{user} elogiou o casaco de {user1}, que respondeu: "É para esconder a adaga." Os dois gargalharam.'),
