  ('FRIENDLY', 'Heroico', '{user} carregou a mala de {user1} e a própria ao mesmo tempo, subindo a colina sem reclamar.'),
  ('FRIENDLY', 'Sonso', '{user} sorriu para {user1} com um sorriso tão doce que ninguém desconfiou de nada.'),
  ('FRIENDLY', 'Fofoqueiro', '{user} contou para {user1} tudo que já sabia sobre os outros convidados. Eram só quinze minutos de jogo.'),
  ('FRIENDLY', NULL, '{user} prometeu a {user1} que, se os dois chegassem à final, pagaria um jantar com o prêmio.'),
  ('FRIENDLY', 'Líder', '{user} reuniu {user1} e mais alguns no canto: "Vamos fazer desse grupo o mais unido da história do programa."'),
  ('FRIENDLY', NULL, '{user} ensinou {user1} a pronunciar "Highlands" com sotaque escocês. Ficou pior.'),
  ('FRIENDLY', 'Carismático', '{user} contou a história da própria vida e {user1} já estava emocionado(a) no segundo capítulo.'),
  ('FRIENDLY', NULL, '{user} e {user1} dividiram o último canapé de salmão como quem assina um tratado de paz.'),
  ('FRIENDLY', 'Querido', '{user} guardou uma taça de champanhe para {user1}, que chegou atrasado(a) e ensopado(a).'),
  ('FRIENDLY', NULL, '"Se eu for assassinado(a), cuida do meu travesseiro", pediu {user} a {user1}, já íntimos.'),
  ('FRIENDLY', NULL, '{user} jurou a {user1} que o castelo tem cheiro de biblioteca antiga. {user1} jurou que é mofo.'),
  ('FRIENDLY', 'Protetor', '{user} viu {user1} tremendo de frio e emprestou o cachecol sem dizer uma palavra.'),
  ('FRIENDLY', 'Amado', 'Bastou {user} entrar no salão para {user1} dizer: "Você eu quero no meu time."'),
  ('FRIENDLY', NULL, '{user} e {user1} combinaram um aperto de mão secreto. Ficou tão complicado que nenhum dos dois lembra.'),

