  ('HUMOR', 'Dramático', '{user} entrou no castelo cantando uma ópera inventada. {user1} aplaudiu por educação.'),
  ('HUMOR', NULL, '{user} perguntou se o castelo tinha elevador. O mordomo nem respondeu.'),
  ('HUMOR', 'Brincalhão', '"Se alguém aqui for traidor, levanta a mão", disse {user}. {user1} quase levantou por reflexo.'),
