  ('HUMOR', 'Brincalhão', '{user} fingiu desmaiar quando ouviu a palavra "assassinato". {user1} não sabia se ria ou chamava o médico.'),
  ('HUMOR', NULL, '{user} disse que veio pelo dinheiro, pela fama e pelo café da manhã, não necessariamente nessa ordem.'),
