  ('HUMOR', NULL, '{user} perguntou se existe seguro de vida no contrato. {user1} riu nervoso(a).'),
  ('HUMOR', 'Arrogante', '{user} disse que já assistiu a todas as temporadas e sabe tudo. Tropeçou no degrau logo depois.'),
  ('HUMOR', NULL, '{user} e {user1} dançaram gaita de foles como se fosse forró. Não era.'),
