  ('HUMOR', NULL, '{user} descobriu que o quarto não tem tomada perto da cama e declarou luto oficial.'),
  ('HUMOR', 'Fofoqueiro', '{user} já criou um grupo imaginário de fofoca chamado "Sussurros da Torre". {user1} foi o primeiro membro.'),

